<?php require_once '../config.php';require_admin();$pdo=db();$flash=get_flash();$products=$pdo->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();$orders=$pdo->query("SELECT o.*,c.name customer FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC LIMIT 8")->fetchAll();$stats=['products'=>(int)$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'customers'=>(int)$pdo->query("SELECT COUNT(*) FROM customers")->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status<>'Cancelled'")->fetchColumn()];?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header><div class="top"><a class="brand" href="../index.php"><span>📖</span><b>Kalpalatha<small>Admin Dashboard</small></b></a><div class="links"><span>Welcome, <?=e($_SESSION['admin_name'])?></span><a href="logout.php">Logout</a></div></div></header><div class="adminwrap"><aside class="side"><a class="sel" href="index.php">📊 Dashboard</a><a href="products.php">📚 Products</a><a href="orders.php">🛒 Orders</a><a href="customers.php">👥 Customers</a><a href="../index.php">🌐 View Store</a></aside><main class="dash"><h1>Dashboard</h1><?php if($flash):?><div class="flash <?=$flash[0]?>"><?=e($flash[1])?></div><?php endif;?><div class="stats"><div><small>Total Products</small><b><?=$stats['products']?></b></div><div><small>Orders</small><b><?=$stats['orders']?></b></div><div><small>Customers</small><b><?=$stats['customers']?></b></div><div><small>Revenue</small><b><?=money($stats['revenue'])?></b></div></div><section class="tablecard"><div class="tablehead"><h2>Products</h2><a class="btn" href="products.php">+ Add Product</a></div><div class="table-scroll"><table><tr><th>ID</th><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr><?php foreach($products as $p):?><tr><td><?=$p['id']?></td><td><?=e($p['image'])?> <?=e($p['name'])?></td><td><?=e($p['category'])?></td><td><?=money((float)$p['price'])?></td><td><?=$p['stock']?></td><td><a href="products.php?edit=<?=$p['id']?>">Edit</a> · <a class="danger" href="products.php?delete=<?=$p['id']?>&csrf=<?=csrf_token()?>" onclick="return confirm('Delete product?')">Delete</a></td></tr><?php endforeach;?></table></div></section><section class="tablecard"><h2>Recent Orders</h2><div class="table-scroll"><table><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o):?><tr><td>#KB<?=str_pad($o['id'],5,'0',STR_PAD_LEFT)?></td><td><?=e($o['customer'])?></td><td><?=money((float)$o['total'])?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></table></div></section></main></div></body></html>